const item = $input.item.json;
const shortlist = item.playerSearch.shortlist;

// Teilt die validierte Shortlist in ein Item je Kandidat auf, damit jeder
// Kandidat einen eigenen, unabhaengigen Research-Zweig erhaelt (naechste
// Nodes: 'Recherche je Kandidat durchfuehren' laeuft separat je Item).
return shortlist.map((candidate) => ({
  json: {
    ...item,
    researchCandidateName: candidate.name
  }
}));

const items = $input.all();
const contextItem = items.find((it) => it.json && it.json.playerSearch) || items[0];
const context = { ...(contextItem ? contextItem.json : {}) };
delete context.researchCandidateName;
delete context.researchResult;

// Fan-in der parallelen Research-Zweige (ein Zweig je Kandidat, siehe
// 'Recherche je Kandidat durchfuehren'). Ein erfolgreicher Zweig liefert
// researchResult mit Quelle/Konfidenz; ein fehlgeschlagener Zweig laeuft ueber
// den Execute-Workflow-Fehlerausgang ein und wird hier NICHT verworfen,
// sondern als Unsicherheit (uncertain: true, confidence 0) am betroffenen
// Kandidaten erhalten, statt die komplette Due Diligence hart ungueltig zu
// machen.
const research = items.map((it) => {
  const j = it.json || {};
  if (j.researchResult) {
    return { ...j.researchResult, uncertain: false, uncertaintyReason: null };
  }

  const candidateName = j.researchCandidateName
    || (j.rankingCandidate && j.rankingCandidate.name)
    || 'unbekannter Kandidat';
  const reason = (j.error && (j.error.message || j.error)) || 'Der Research-Zweig fuer diesen Kandidaten ist fehlgeschlagen.';

  return {
    candidate: candidateName,
    club: null,
    contract: null,
    marketValue: null,
    injuries: null,
    news: [],
    source: 'Recherche fehlgeschlagen (keine Quelle verfuegbar)',
    timestamp: new Date().toISOString(),
    confidence: 0,
    uncertain: true,
    uncertaintyReason: reason
  };
});

return [{ json: { ...context, research } }];

const item = $input.item.json;
const research = item.research;
const shortlistNames = (item.playerSearch && Array.isArray(item.playerSearch.shortlist))
  ? item.playerSearch.shortlist.map((c) => c.name)
  : [];
const errors = [];

if (!Array.isArray(research) || research.length === 0) {
  errors.push('research fehlt oder ist leer.');
} else {
  const researchedNames = research.map((r) => r.candidate).filter((name) => !!name);
  const uniqueResearchedNames = new Set(researchedNames);
  const shortlistSet = new Set(shortlistNames);

  if (researchedNames.length !== uniqueResearchedNames.size) {
    errors.push('research enthaelt denselben Kandidaten mehrfach.');
  }
  const missing = shortlistNames.filter((name) => !uniqueResearchedNames.has(name));
  if (missing.length > 0) {
    errors.push(`research deckt folgende Shortlist-Kandidaten nicht ab: ${missing.join(', ')}.`);
  }
  const unexpected = [...uniqueResearchedNames].filter((name) => !shortlistSet.has(name));
  if (unexpected.length > 0) {
    errors.push(`research enthaelt Kandidaten ausserhalb der Shortlist: ${unexpected.join(', ')}.`);
  }

  research.forEach((r, idx) => {
    if (!r.candidate || !shortlistSet.has(r.candidate)) errors.push(`research[${idx}].candidate fehlt oder ist nicht Teil der Shortlist.`);
    if (typeof r.confidence !== 'number') errors.push(`research[${idx}].confidence (Konfidenz) fehlt oder ist keine Zahl.`);
    if (!r.source) errors.push(`research[${idx}].source (Quelle) fehlt.`);
    if (!r.timestamp) errors.push(`research[${idx}].timestamp (Zeitpunkt) fehlt.`);
    if (!Array.isArray(r.news)) errors.push(`research[${idx}].news (Meldungen) ist kein Array.`);

    // Ein fehlgeschlagener Research-Zweig bleibt als Unsicherheit am
    // Kandidaten erhalten (r.uncertain = true) statt die gesamte Due
    // Diligence hart ungueltig zu machen - nur ein erfolgreicher Zweig muss
    // die vollen fachlichen Detailfelder liefern.
    if (!r.uncertain) {
      if (!r.club) errors.push(`research[${idx}].club (Verein) fehlt.`);
      if (!r.contract) errors.push(`research[${idx}].contract (Vertrag) fehlt.`);
      if (!r.marketValue) errors.push(`research[${idx}].marketValue (Marktwert) fehlt.`);
      if (!r.injuries) errors.push(`research[${idx}].injuries (Verletzungen) fehlt.`);
      if (Array.isArray(r.news) && r.news.length === 0) errors.push(`research[${idx}].news (Meldungen) ist leer.`);
    }
  });

  if (research.length > 0 && research.every((r) => r.uncertain)) {
    errors.push('Fuer keinen Kandidaten der Shortlist konnte eine Recherche erfolgreich durchgefuehrt werden (alle Research-Zweige sind als Unsicherheit markiert).');
  }
}

const valid = errors.length === 0;

return [{
  json: {
    ...item,
    valid,
    errorMessage: valid
      ? undefined
      : 'Die Recherche ist ungueltig und wird nicht fuer die Empfehlung verwendet.\n\n' + errors.join('\n')
  }
}];
